1	//! Implementation of the [`IErc1155Receiver`] trait.
2	use alloc::{vec, vec::Vec};
3	
4	use alloy_primitives::{aliases::B32, Address, U256};
5	use stylus_sdk::{abi::Bytes, function_selector, prelude::*};
6	
7	use crate::{
8	    token::erc1155::receiver::{
9	        IErc1155Receiver, BATCH_TRANSFER_FN_SELECTOR,
10	        SINGLE_TRANSFER_FN_SELECTOR},
11	    utils::introspection::erc165::IErc165};
12	
13	/// Simple implementation of [`IErc1155Receiver`] that will allow a contract to
14	/// hold ERC-1155 tokens.
15	#[storage]
16	pub struct Erc1155Holder;
17	
18	#[public]
19	#[implements(IErc1155Receiver, IErc165)]
20	impl Erc1155Holder {}
21	
22	#[public]
23	impl IErc1155Receiver for Erc1155Holder {
24	    #[selector(name = "onERC1155Received")]
25	    fn on_erc1155_received(
26	        &mut self,
27	        _operator: Address,
28	        _from: Address,
29	        _id: U256,
30	        _value: U256,
31	        _data: Bytes,
32	    ) -> Result<B32, Vec<u8>> {
33	        Ok(SINGLE_TRANSFER_FN_SELECTOR)
34	    }
35	
36	    #[selector(name = "onERC1155BatchReceived")]
37	    fn on_erc1155_batch_received(
38	        &mut self,
39	        _operator: Address,
40	        _from: Address,
41	        _ids: Vec<U256>,
42	        _values: Vec<U256>,
43	        _data: Bytes,
44	    ) -> Result<B32, Vec<u8>> {
45	        Ok(BATCH_TRANSFER_FN_SELECTOR)
46	    }
47	}
48	
49	#[public]
50	impl IErc165 for Erc1155Holder {
51	    fn supports_interface(&self, interface_id: B32) -> bool {
52	        <Self as IErc1155Receiver>::interface_id() == interface_id
53	            || <Self as IErc165>::interface_id() == interface_id
54	    }
55	}
56	
57	#[cfg(test)]
58	mod tests {
59	    use motsu::prelude::Contract;
60	
61	    use super::*;
62	
63	    unsafe impl TopLevelStorage for Erc1155Holder {}
64	
65	    #[motsu::test]
66	    fn holder_returns_proper_selectors(
67	        contract: Contract<Erc1155Holder>,
68	        alice: Address,
69	    ) {
70	        let one = U256::from(1);
71	        assert_eq!(
72	            contract.sender(alice).on_erc1155_received(
73	                alice,
74	                alice,
75	                one,
76	                one,
77	                vec![].into()
78	            ),
79	            Ok(SINGLE_TRANSFER_FN_SELECTOR)
80	        );
81	
82	        assert_eq!(
83	            contract.sender(alice).on_erc1155_batch_received(
84	                alice,
85	                alice,
86	                vec![one],
87	                vec![one],
88	                vec![].into()
89	            ),
90	            Ok(BATCH_TRANSFER_FN_SELECTOR)
91	        );
92	    }
93	
94	    #[motsu::test]
95	    fn supports_interface(contract: Contract<Erc1155Holder>, alice: Address) {
96	        assert!(contract.sender(alice).supports_interface(
97	            <Erc1155Holder as IErc1155Receiver>::interface_id()
98	        ));
99	        assert!(contract
100	            .sender(alice)
101	            .supports_interface(<Erc1155Holder as IErc165>::interface_id()));
102	
103	        let fake_interface_id: B32 = 0x12345678_u32.into();
104	        assert!(!contract.sender(alice).supports_interface(fake_interface_id));
105	    }
106	}
