1	//! Optional Burnable extension of the ERC-1155 standard.
2	
3	use alloc::vec::Vec;
4	use stylus_sdk::prelude::public;
5	
6	use alloy_primitives::{Address, U256};
7	use openzeppelin_stylus_proc::interface_id;
8	
9	use crate::token::erc1155::{
10	    self, ERC1155MissingApprovalForAll, Erc1155, IErc1155};
11	
12	/// Extension of [`Erc1155`] that allows token holders to destroy both their
13	/// own tokens and those that they have been approved to use.
14	#[interface_id]
15	#[public]
16	pub trait IErc1155Burnable {
17	    /// The error type associated to this trait implementation.
18	    type Error: Into<alloc::vec::Vec<u8>>;
19	
20	    /// Destroys a `value` amount of token from `account`.
21	    ///
22	    /// # Arguments
23	    ///
24	    /// * `&mut self` - Write access to the contract's state.
25	    /// * `account` - Account to burn tokens from.
26	    /// * `token_id` - Token id to be burnt.
27	    /// * `value` - Amount to be burnt.
28	    ///
29	    /// # Errors
30	    ///
31	    /// * [`erc1155::Error::MissingApprovalForAll`] - If the caller is not
32	    ///   `account` address and the `account` has not been approved.
33	    /// * [`erc1155::Error::InvalidSender`] - If `from` is the
34	    ///   [`Address::ZERO`].
35	    /// * [`erc1155::Error::InsufficientBalance`] - If `value` is greater than
36	    ///   the balance of the `from` account.
37	    fn burn(
38	        &mut self,
39	        account: Address,
40	        token_id: U256,
41	        value: U256,
42	    ) -> Result<(), Self::Error>;
43	
44	    /// Destroys a batch of tokens from `account`.
45	    ///
46	    /// # Arguments
47	    ///
48	    /// * `&mut self` - Write access to the contract's state.
49	    /// * `account` - Accounts to burn tokens from.
50	    /// * `token_ids` - All token id to be burnt.
51	    /// * `values` - All amount to be burnt.
52	    ///
53	    /// # Errors
54	    ///
55	    /// * [`erc1155::Error::MissingApprovalForAll`] - If the caller is not
56	    ///   `account` address and the `account` has not been approved.
57	    /// * [`erc1155::Error::InvalidSender`] - If `from` is the
58	    ///   [`Address::ZERO`].
59	    /// * [`erc1155::Error::InvalidArrayLength`] - If length of `ids` is not
60	    ///   equal to length of `values`.
61	    /// * [`erc1155::Error::InsufficientBalance`] - If any of the `values` is
62	    ///   greater than the balance of the respective token from `tokens` of the
63	    ///   `from` account.
64	    fn burn_batch(
65	        &mut self,
66	        account: Address,
67	        token_ids: Vec<U256>,
68	        values: Vec<U256>,
69	    ) -> Result<(), Self::Error>;
70	}
71	
72	#[public]
73	impl IErc1155Burnable for Erc1155 {
74	    type Error = erc1155::Error;
75	
76	    fn burn(
77	        &mut self,
78	        account: Address,
79	        token_id: U256,
80	        value: U256,
81	    ) -> Result<(), Self::Error> {
82	        self.ensure_approved_or_owner(account)?;
83	        self._burn(account, token_id, value)
84	    }
85	
86	    fn burn_batch(
87	        &mut self,
88	        account: Address,
89	        token_ids: Vec<U256>,
90	        values: Vec<U256>,
91	    ) -> Result<(), Self::Error> {
92	        self.ensure_approved_or_owner(account)?;
93	        self._burn_batch(account, token_ids, values)
94	    }
95	}
96	
97	impl Erc1155 {
98	    fn ensure_approved_or_owner(
99	        &self,
100	        account: Address,
101	    ) -> Result<(), erc1155::Error> {
102	        let sender = self.vm().msg_sender();
103	        if account != sender && !self.is_approved_for_all(account, sender) {
104	            return Err(erc1155::Error::MissingApprovalForAll(
105	                ERC1155MissingApprovalForAll {
106	                    owner: account,
107	                    operator: sender},
108	            ));
109	        }
110	        Ok(())
111	    }
112	}
