1	//! ERC-1155 token with storage based token URI management.
2	//!
3	//! Inspired by the [`crate::token::erc721::extensions::Erc721UriStorage`]
4	use alloc::{string::String, vec, vec::Vec};
5	
6	use alloy_primitives::U256;
7	use openzeppelin_stylus_proc::interface_id;
8	use stylus_sdk::{prelude::*, storage::{StorageMap, StorageString}};
9	
10	use super::metadata_uri::{IErc1155MetadataUri, URI};
11	
12	/// State of an [`Erc1155UriStorage`] contract.
13	#[storage]
14	pub struct Erc1155UriStorage {
15	    /// Optional base URI.
16	    pub(crate) base_uri: StorageString,
17	    /// Optional mapping for token URIs.
18	    pub(crate) token_uris: StorageMap<U256, StorageString>}
19	
20	/// Interface of an optional extension for ERC-1155 with storage based token URI
21	/// management.
22	#[interface_id]
23	#[public]
24	pub trait IErc1155UriStorage {
25	    /// Returns the Uniform Resource Identifier (URI) for `token_id` token.
26	    ///
27	    /// # Arguments
28	    ///
29	    /// * `&self` - Read access to the contract's state.
30	    /// * `token_id` - Id of a token.
31	    fn uri(&self, token_id: U256) -> String;
32	}
33	
34	impl Erc1155UriStorage {
35	    /// See [`IErc1155UriStorage::uri`].
36	    pub fn uri(
37	        &self,
38	        token_id: U256,
39	        metadata_uri: &impl IErc1155MetadataUri,
40	    ) -> String {
41	        let token_uri = self.token_uris.get(token_id).get_string();
42	
43	        if token_uri.is_empty() {
44	            metadata_uri.uri(token_id)
45	        } else {
46	            self.base_uri.get_string() + &token_uri
47	        }
48	    }
49	
50	    /// Sets `token_uri` as the tokenURI of `token_id`.
51	    ///
52	    /// # Arguments
53	    ///
54	    /// * `&mut self` - Write access to the contract's state.
55	    /// * `token_id` - Id of a token.
56	    /// * `token_uri` - URI for the token.
57	    /// * `metadata_uri` - Read access to a contract providing
58	    ///   [`IErc1155MetadataUri`] interface.
59	    ///
60	    /// # Events
61	    ///
62	    /// * [`URI`].
63	    pub fn set_token_uri(
64	        &mut self,
65	        token_id: U256,
66	        token_uri: String,
67	        metadata_uri: &impl IErc1155MetadataUri,
68	    ) {
69	        self.token_uris.setter(token_id).set_str(token_uri);
70	        self.vm().log(URI { value: self.uri(token_id, metadata_uri), id: token_id });
71	    }
72	
73	    /// Sets `base_uri` as the `base_uri` for all tokens.
74	    ///
75	    /// # Arguments
76	    ///
77	    /// * `&mut self` - Write access to the contract's state.
78	    /// * `base_uri` - New base URI.
79	    pub fn set_base_uri(&mut self, base_uri: String) {
80	        self.base_uri.set_str(base_uri);
81	    }
82	}
