202	impl Erc1155Supply {
203	    /// Extended version of [`Erc1155::_update`] that updates the supply of
204	    /// tokens.
205	    ///
206	    /// NOTE: The ERC-1155 acceptance check is not performed in this function.
207	    /// See [`Self::_update_with_acceptance_check`] instead.
208	    ///
209	    /// # Arguments
210	    ///
211	    /// * `&mut self` - Write access to the contract's state.
212	    /// * `from` - Account of the sender.
213	    /// * `to` - Account of the recipient.
214	    /// * `token_ids` - Array of all token id.
215	    /// * `values` - Array of all amount of tokens to be supplied.
216	    ///
217	    /// # Errors
218	    ///
219	    /// * [`erc1155::Error::InvalidArrayLength`] - If length of `ids` is not
220	    ///   equal to length of `values`.
221	    /// * [`erc1155::Error::InsufficientBalance`] - If `value` is greater than
222	    ///   the balance of the `from` account.
223	    ///
224	    /// # Events
225	    ///
226	    /// * [`erc1155::TransferSingle`] - If the arrays contain one element.
227	    /// * [`erc1155::TransferBatch`] - If the arrays contain more than one
228	    ///   element.
229	    ///
230	    /// # Panics
231	    ///
232	    /// * If updated balance and/or supply exceeds [`U256::MAX`], may happen
233	    ///   during the `mint` operation.
234	    fn _update(
235	        &mut self,
236	        from: Address,
237	        to: Address,
238	        token_ids: Vec<U256>,
239	        values: Vec<U256>,
240	    ) -> Result<(), erc1155::Error> {
241	        self.erc1155._update(from, to, token_ids.clone(), values.clone())?;
242	
243	        if from.is_zero() {
244	            for (&token_id, &value) in token_ids.iter().zip(values.iter()) {
245	                self.total_supply.setter(token_id).add_assign_checked(
246	                    value,
247	                    "should not exceed `U256::MAX` for `total_supply`",
248	                );
249	            }
250	
251	            let total_mint_value = values.iter().sum();
252	            self.total_supply_all.add_assign_checked(
253	                total_mint_value,
254	                "should not exceed `U256::MAX` for `total_supply_all`",
255	            );
256	        }
257	
258	        if to.is_zero() {
259	            for (token_id, &value) in token_ids.into_iter().zip(values.iter()) {
260	                /*
261	                 * SAFETY: Overflow not possible:
262	                 * values[i] <= balance_of(from, token_ids[i]) <=
263	                 * total_supply(token_ids[i])
264	                 */
265	                self.total_supply.setter(token_id).sub_assign_unchecked(value);
266	            }
267	
268	            let total_burn_value: U256 = values.into_iter().sum();
269	            /*
270	             * SAFETY: Overflow not possible:
271	             * total_burn_value = sum_i(values[i]) <=
272	             * sum_i(total_supply(ids[i])) <= total_supply_all
273	             */
274	            self.total_supply_all.sub_assign_unchecked(total_burn_value);
275	        }
276	        Ok(())
277	    }
278	
279	    fn _update_with_acceptance_check(
280	        &mut self,
281	        from: Address,
282	        to: Address,
283	        ids: Vec<U256>,
284	        values: Vec<U256>,
285	        data: &Bytes,
286	    ) -> Result<(), erc1155::Error> {
287	        self._update(from, to, ids.clone(), values.clone())?;
288	
289	        if !to.is_zero() {
290	            self.erc1155._check_on_erc1155_received(
291	                self.vm().msg_sender(),
292	                from,
293	                to,
294	                erc1155::Erc1155ReceiverData::new(ids, values),
295	                data.to_vec().into(),
296	            )?;
297	        }
298	
299	        Ok(())
300	    }
301	
302	    fn _do_mint(
303	        &mut self,
304	        to: Address,
305	        ids: Vec<U256>,
306	        values: Vec<U256>,
307	        data: &Bytes,
308	    ) -> Result<(), erc1155::Error> {
309	        if to.is_zero() {
310	            return Err(erc1155::Error::InvalidReceiver(
311	                erc1155::ERC1155InvalidReceiver { receiver: to },
312	            ));
313	        }
314	        self._update_with_acceptance_check(
315	            Address::ZERO,
316	            to,
317	            ids,
318	            values,
319	            data,
320	        )?;
321	        Ok(())
322	    }
