324	    fn _do_burn(
325	        &mut self,
326	        from: Address,
327	        ids: Vec<U256>,
328	        values: Vec<U256>,
329	    ) -> Result<(), erc1155::Error> {
330	        if from.is_zero() {
331	            return Err(erc1155::Error::InvalidSender(
332	                erc1155::ERC1155InvalidSender { sender: from },
333	            ));
334	        }
335	        self._update_with_acceptance_check(
336	            from,
337	            Address::ZERO,
338	            ids,
339	            values,
340	            &vec![].into(),
341	        )?;
342	        Ok(())
343	    }
