/// Interface of the ERC-165 standard, as defined in the [ERC].
///
/// Implementers can declare support of contract interfaces, which others can
/// query.
///
/// # Example
///
/// ```rust,ignore
/// impl IErc165 for Erc20 {
///     fn supports_interface(&self, interface_id: B32) -> bool {
