            DAVE,
            token_ids[0],
            amount_one,
            vec![].into(),
        )
        .expect("should transfer tokens from Alice to Bob");
    contract
        .safe_transfer_from(
            BOB,
            DAVE,
            token_ids[1],
            amount_two,
            vec![].into(),
        )
        .expect("should transfer tokens from Alice to Bob");

    let balance_id_one =
        contract.balance_of(DAVE, token_ids[0]);
    let balance_id_two =
        contract.balance_of(DAVE, token_ids[1]);

    assert_eq!(amount_one, balance_id_one);
    assert_eq!(amount_two, balance_id_two);
}

