#!/usr/bin/env python3
"""Check that converted tests keep exactly the same statements as the originals.

For every test function (old: `#[motsu::test]`/`#[test]` at the base commit,
new: `#[test]` in the worktree) we normalise away what the migration changes on
purpose (motsu fixtures, `.sender(x)`, `vm`/`contract` creation,
`vm.set_sender`, account names) and compare the remaining token stream.
"""
import re
import subprocess
import sys

BASE = "47ad800"
FILES = [
    "contracts/src/token/erc1155/mod.rs",
    "contracts/src/token/erc1155/extensions/burnable.rs",
    "contracts/src/token/erc1155/extensions/supply.rs",
    "contracts/src/token/erc1155/extensions/metadata_uri.rs",
    "contracts/src/token/erc1155/extensions/uri_storage.rs",
    "contracts/src/token/erc1155/utils/holder.rs",
]
NAMES = {"alice": "ALICE", "bob": "BOB", "dave": "DAVE", "charlie": "CHARLIE"}


def old_src(path):
    return subprocess.check_output(["git", "show", f"{BASE}:{path}"], text=True)


def new_src(path):
    return open(path).read()


def match_brace(src, open_idx):
    """Index of the `}` matching the `{` at open_idx (skips strings/comments)."""
    depth = 0
    i = open_idx
    n = len(src)
    while i < n:
        c = src[i]
        if c == '"':
            i += 1
            while src[i] != '"':
                if src[i] == "\\":
                    i += 1
                i += 1
        elif c == "/" and src[i : i + 2] == "//":
            i = src.index("\n", i)
            continue
        elif c == "{":
            depth += 1
        elif c == "}":
            depth -= 1
            if depth == 0:
                return i
        i += 1
    raise ValueError("unbalanced")


FN_HEAD = re.compile(
    r"((?:[ \t]*#\[[^\n]*\]\n)*)[ \t]*fn (\w+)\(([^)]*)\)\s*(?:->[^{]*)?\{", re.M
)


def test_fns(src):
    """name -> (attrs, params, body) for fns inside the tests module that are tests."""
    start = src.index("#[cfg(test)]\nmod tests {")
    sec = src[start:]
    out = {}
    for m in FN_HEAD.finditer(sec):
        attrs, name, params = m.group(1), m.group(2), m.group(3)
        if "#[motsu::test]" not in attrs and "#[test]" not in attrs:
            continue
        open_idx = m.end() - 1
        close_idx = match_brace(sec, open_idx)
        body = sec[open_idx + 1 : close_idx]
        assert name not in out, name
        out[name] = (attrs, params, body)
    return out


def squash(text):
    return re.sub(r"\s+", "", text)


def norm_common(text):
    text = squash(text)
    text = re.sub(r",([)\]}])", r"\1", text)  # trailing commas
    return text


def upper(text):
    # outside string literals only
    def repl(m):
        return m.group(0) if m.group(1) is None else NAMES[m.group(1)]

    return re.sub(r'"(?:[^"\\]|\\.)*"|\b(alice|bob|dave|charlie)\b', repl, text)


def norm_old(attrs, params, body):
    body = re.sub(r"contract\s*\.sender\(\w+\)", "contract", body)
    body = upper(body)
    attrs = attrs.replace("#[motsu::test]", "#[test]")
    return norm_common(attrs + body)


def norm_new(attrs, params, body):
    body = re.sub(r"\n\s*let vm = TestVM::default\(\);", "", body)
    body = re.sub(r"\n\s*let (?:mut )?contract = \w+::from\(&vm\);", "", body)
    body = re.sub(r"\n\s*vm\.set_sender\(\w+\);", "", body)
    return norm_common(attrs + body)


def main():
    bad = 0
    total = 0
    for path in FILES:
        old = test_fns(old_src(path))
        new = test_fns(new_src(path))
        if set(old) != set(new):
            print(f"{path}: name mismatch: only-old={sorted(set(old)-set(new))} "
                  f"only-new={sorted(set(new)-set(old))}")
            bad += 1
        for name in sorted(set(old) & set(new)):
            total += 1
            a = norm_old(*old[name])
            b = norm_new(*new[name])
            if a != b:
                bad += 1
                print(f"MISMATCH {path}::{name}")
                # show first divergence
                k = next((i for i, (x, y) in enumerate(zip(a, b)) if x != y), min(len(a), len(b)))
                print("   old:", a[max(0, k - 60) : k + 80])
                print("   new:", b[max(0, k - 60) : k + 80])
    print(f"compared {total} test fns, {bad} problems")
    sys.exit(1 if bad else 0)


if __name__ == "__main__":
    main()

