//! Throwaway checks of the receiver acceptance path with mocked calls.
use alloy_primitives::{address, aliases::B32, Address, U256};
use alloy_sol_types::SolValue;
use stylus_sdk::testing::TestVM;

use crate::{
    test_utils::{ALICE, BOB},
    token::erc1155::{
        Error, Erc1155, IErc1155, BATCH_TRANSFER_FN_SELECTOR,
        SINGLE_TRANSFER_FN_SELECTOR,
    },
};

const RECEIVER: Address = address!("0000000000000000000000000000000000000abc");

fn single_calldata(
    operator: Address,
    from: Address,
    id: U256,
    value: U256,
    data: Vec<u8>,
) -> Vec<u8> {
    let mut cd = SINGLE_TRANSFER_FN_SELECTOR_SIG.to_vec();
    cd.extend((operator, from, id, value, alloy_primitives::Bytes::from(data)).abi_encode_params());
    cd
}

fn batch_calldata(
    operator: Address,
    from: Address,
    ids: Vec<U256>,
    values: Vec<U256>,
    data: Vec<u8>,
) -> Vec<u8> {
    let mut cd = BATCH_SIG.to_vec();
    cd.extend((operator, from, ids, values, alloy_primitives::Bytes::from(data)).abi_encode_params());
    cd
}

// 4-byte selectors of the receiver functions (what the code under test calls).
const SINGLE_TRANSFER_FN_SELECTOR_SIG: [u8; 4] = [0xf2, 0x3a, 0x6e, 0x61];
const BATCH_SIG: [u8; 4] = [0xbc, 0x19, 0x7c, 0x81];

fn ret(selector: B32) -> Vec<u8> {
    let mut out = [0u8; 32];
    out[..4].copy_from_slice(selector.as_slice());
    out.to_vec()
}

fn setup() -> (TestVM, Erc1155) {
    let vm = TestVM::default();
    let mut contract = Erc1155::from(&vm);
    vm.set_sender(ALICE);
    contract._mint(ALICE, U256::from(1), U256::from(10), &vec![].into()).unwrap();
    contract._mint(ALICE, U256::from(2), U256::from(20), &vec![].into()).unwrap();
    vm.set_code(RECEIVER, vec![0x60, 0x00]);
    (vm, contract)
}

#[test]
fn selectors_match() {
    assert_eq!(SINGLE_TRANSFER_FN_SELECTOR.as_slice(), &SINGLE_TRANSFER_FN_SELECTOR_SIG);
    assert_eq!(BATCH_TRANSFER_FN_SELECTOR.as_slice(), &BATCH_SIG);
}

#[test]
fn single_accepted() {
    let (vm, mut contract) = setup();
    vm.mock_call(
        RECEIVER,
        single_calldata(ALICE, ALICE, U256::from(1), U256::from(4), vec![7]),
        U256::ZERO,
        Ok(ret(SINGLE_TRANSFER_FN_SELECTOR)),
    );
    contract
        .safe_transfer_from(ALICE, RECEIVER, U256::from(1), U256::from(4), vec![7].into())
        .expect("receiver accepts");
    assert_eq!(U256::from(4), contract.balance_of(RECEIVER, U256::from(1)));
    assert_eq!(U256::from(6), contract.balance_of(ALICE, U256::from(1)));
}

#[test]
fn single_wrong_selector() {
    let (vm, mut contract) = setup();
    vm.mock_call(
        RECEIVER,
        single_calldata(ALICE, ALICE, U256::from(1), U256::from(4), vec![]),
        U256::ZERO,
        Ok(ret(B32::from([0xde, 0xad, 0xbe, 0xef]))),
    );
    let err = contract
        .safe_transfer_from(ALICE, RECEIVER, U256::from(1), U256::from(4), vec![].into())
        .expect_err("wrong selector");
    assert!(matches!(err, Error::InvalidReceiver(r) if r.receiver == RECEIVER));
}

#[test]
fn single_revert_with_reason() {
    let (vm, mut contract) = setup();
    vm.mock_call(
        RECEIVER,
        single_calldata(ALICE, ALICE, U256::from(1), U256::from(4), vec![]),
        U256::ZERO,
        Err(b"nope".to_vec()),
    );
    let err = contract
        .safe_transfer_from(ALICE, RECEIVER, U256::from(1), U256::from(4), vec![].into())
        .expect_err("reverts");
    assert!(matches!(err, Error::InvalidReceiverWithReason(r) if r.reason == "nope"));
}

#[test]
fn single_revert_without_reason() {
    let (vm, mut contract) = setup();
    vm.mock_call(
        RECEIVER,
        single_calldata(ALICE, ALICE, U256::from(1), U256::from(4), vec![]),
        U256::ZERO,
        Err(vec![]),
    );
    let err = contract
        .safe_transfer_from(ALICE, RECEIVER, U256::from(1), U256::from(4), vec![].into())
        .expect_err("reverts");
    assert!(matches!(err, Error::InvalidReceiver(r) if r.receiver == RECEIVER));
}

#[test]
fn batch_accepted_with_operator() {
    let (vm, mut contract) = setup();
    // BOB is approved and acts as the operator.
    contract.set_approval_for_all(BOB, true).unwrap();
    vm.set_sender(BOB);
    vm.mock_call(
        RECEIVER,
        batch_calldata(BOB, ALICE, vec![U256::from(1), U256::from(2)], vec![U256::from(3), U256::from(5)], vec![]),
        U256::ZERO,
        Ok(ret(BATCH_TRANSFER_FN_SELECTOR)),
    );
    contract
        .safe_batch_transfer_from(
            ALICE,
            RECEIVER,
            vec![U256::from(1), U256::from(2)],
            vec![U256::from(3), U256::from(5)],
            vec![].into(),
        )
        .expect("receiver accepts batch");
    assert_eq!(U256::from(3), contract.balance_of(RECEIVER, U256::from(1)));
    assert_eq!(U256::from(5), contract.balance_of(RECEIVER, U256::from(2)));
}

#[test]
fn mint_to_contract_runs_check() {
    let (vm, mut contract) = setup();
    vm.mock_call(
        RECEIVER,
        single_calldata(ALICE, Address::ZERO, U256::from(9), U256::from(1), vec![]),
        U256::ZERO,
        Ok(ret(B32::from([1, 2, 3, 4]))),
    );
    let err = contract
        ._mint(RECEIVER, U256::from(9), U256::from(1), &vec![].into())
        .expect_err("rejected");
    assert!(matches!(err, Error::InvalidReceiver(_)));
}
