#!/usr/bin/env python3
"""Build the intermediate file states used for the small logical commits.

Usage: mkstates.py STATE   where STATE is one of c1 c2 c3 c4 c5
Writes the requested state into the worktree (from the saved final files and
the files at HEAD, which must be the base commit for the first state).
"""
import os
import re
import shutil
import subprocess
import sys
import tempfile

WT = "/tmp/bench/wt/erc1155"
FINAL = "/tmp/bench/exp/erc1155-final/erc1155"
PREFIX = "contracts/src/token/erc1155"
BASE_REV = "7e36233"
FILES = [
    "mod.rs",
    "receiver.rs",
    "utils/holder.rs",
    "extensions/burnable.rs",
    "extensions/metadata_uri.rs",
    "extensions/supply.rs",
    "extensions/uri_storage.rs",
]
MARK = "#[cfg(test)]\nmod tests {"
FMT = ["rustfmt", "+nightly-2025-08-01", "--edition", "2021"]


def base_text(rel):
    return subprocess.check_output(
        ["git", "-C", WT, "show", f"{BASE_REV}:{PREFIX}/{rel}"], text=True
    )


def final_text(rel):
    return open(os.path.join(FINAL, rel)).read()


def split(text):
    if MARK not in text:
        return text, ""
    i = text.index(MARK)
    return text[:i], text[i:]


def match_brace(src, open_idx):
    depth = 0
    i = open_idx
    while True:
        c = src[i]
        if c == '"':
            i += 1
            while src[i] != '"':
                if src[i] == "\\":
                    i += 1
                i += 1
        elif c == "/" and src[i : i + 2] == "//":
            i = src.index("\n", i)
            continue
        elif c == "{":
            depth += 1
        elif c == "}":
            depth -= 1
            if depth == 0:
                return i
        i += 1


# --- reversal of the later logical changes on the non-test part -------------

TRAIT_TAG = "#[public]\n#[allow(missing_docs)]\npub trait "


def reverse_c3(rel, nt):
    """Undo the lint allowances for macro-generated items."""
    nt = nt.replace(TRAIT_TAG, "#[public]\npub trait ")
    if rel == "receiver.rs":
        nt = nt.replace("        #[allow(clippy::too_many_arguments)]\n", "")
    return nt


IMPLS = {
    "mod.rs": ("impl IErc1155 for Erc1155 {", None),
    "extensions/supply.rs": ("impl IErc1155 for Erc1155Supply {", "erc1155::Error"),
    "extensions/burnable.rs": ("impl IErc1155Burnable for Erc1155 {", "erc1155::Error"),
}


def reverse_c2(rel, nt):
    """Use `Self::Error` again in the `#[public]` trait impls."""
    if rel not in IMPLS:
        return nt
    header, _ = IMPLS[rel]
    start = nt.index(header)
    open_idx = nt.index("{", start)
    close_idx = match_brace(nt, open_idx)
    block = nt[open_idx : close_idx + 1]
    block = re.sub(r"(Result<[^;{]*?,\s*)(?:erc1155::)?Error>", r"\1Self::Error>", block)
    return nt[:open_idx] + block + nt[close_idx + 1 :]


def fmt_nontest(files_text):
    """rustfmt a whole tree of full-file texts; return the formatted texts."""
    with tempfile.TemporaryDirectory(dir="/tmp/bench/exp") as tmp:
        root = os.path.join(tmp, PREFIX)
        for rel, text in files_text.items():
            p = os.path.join(root, rel)
            os.makedirs(os.path.dirname(p), exist_ok=True)
            open(p, "w").write(text)
        # extension/utils module declaration files
        for rel in ("extensions/mod.rs", "utils/mod.rs"):
            p = os.path.join(root, rel)
            os.makedirs(os.path.dirname(p), exist_ok=True)
            open(p, "w").write(open(os.path.join(FINAL, rel)).read())
        shutil.copy(os.path.join(WT, "rustfmt.toml"), os.path.join(tmp, "rustfmt.toml"))
        subprocess.check_call(
            FMT + [os.path.join(root, "mod.rs")], cwd=tmp
        )
        return {rel: open(os.path.join(root, rel)).read() for rel in files_text}


def build(state):
    n = int(state[1])
    out = {}
    drafts = {}
    for rel in FILES:
        f_nt, f_t = split(final_text(rel))
        b_nt, b_t = split(base_text(rel))
        nt = f_nt
        if n < 3:
            nt = reverse_c3(rel, nt)
        if n < 2:
            nt = reverse_c2(rel, nt)
        # tests part
        if n >= 5 or (n >= 4 and rel == "mod.rs"):
            t = f_t
        else:
            t = b_t
        drafts[rel] = nt + (t if t else "")
    formatted = fmt_nontest(drafts)
    for rel in FILES:
        f_nt, f_t = split(final_text(rel))
        b_nt, b_t = split(base_text(rel))
        fm_nt, _ = split(formatted[rel])
        if n >= 5 or (n >= 4 and rel == "mod.rs"):
            t = f_t
        else:
            t = b_t
        out[rel] = fm_nt + t
    return out


def main():
    state = sys.argv[1]
    out = build(state)
    for rel, text in out.items():
        open(os.path.join(WT, PREFIX, rel), "w").write(text)
    print("wrote state", state)


if __name__ == "__main__":
    main()

